import http from "http";
export default function express(){const mws=[],routes=[];const app={use(f){mws.push(f)},listen(p,cb){http.createServer((req,res)=>{let b="";req.on("data",d=>b+=d);req.on("end",()=>{const u=new URL(req.url,"http://x");req.query=Object.fromEntries(u.searchParams);req.params={};try{req.body=b?JSON.parse(b):undefined}catch{}
res.status=c=>{res.statusCode=c;return res};res.set=(k,v)=>{res.setHeader(k,v);return res};res.json=o=>{res.setHeader("Content-Type","application/json");res.end(JSON.stringify(o))};res.send=t=>res.end(t);res.sendFile=()=>res.end();
const r=routes.find(r=>r.m===req.method&&[].concat(r.p).includes(u.pathname));const chain=[...mws,...(r?r.h:[(q,s)=>{s.statusCode=404;s.end()}])];
let i=0;const next=()=>{const h=chain[i++];h&&h(req,res,next)};next()})}).listen(p,cb)}};
for(const m of ["get","post","delete"])app[m]=(p,...h)=>routes.push({m:m.toUpperCase(),p,h});return app}
express.json=()=>(q,s,n)=>n();
